namespace MyApp.Tests;

[System.Diagnostics.CodeAnalysis.SuppressMessage("", "MSTESTEXP")]
public sealed class RetryAttribute : RetryBaseAttribute
{
    private readonly int _retryCount;

    public RetryAttribute(int retryCount = 3)
    {
        _retryCount = retryCount;
    }

    public override async Task<RetryResult> ExecuteAsync(RetryContext context)
    {
        var result = new RetryResult();
        result.AddResult(context.FirstRunResults);

        for (int i = 1; i < _retryCount; i++)
        {
            var lastResult = result.LastResult();
            if (lastResult is not null && lastResult[0].Outcome == UnitTestOutcome.Passed)
                break;

            var attempt = await context.ExecuteTaskGetter();
            result.AddResult(attempt);
        }

        return result;
    }
}

