 using System.Threading.Tasks;
 using Microsoft.VisualStudio.TestTools.UnitTesting;

 namespace MyApp.Tests;

 #pragma warning disable MSTESTEXP
 public class RetryAttribute : RetryBaseAttribute
 {
     private readonly int _retryCount;

     public RetryAttribute(int retryCount = 3)
     {
         _retryCount = retryCount;
     }

     protected override async Task<RetryResult> ExecuteAsync(RetryContext context)
     {
         var result = new RetryResult();
         result.AddResult(context.FirstRunResults);

         for (int i = 1; i < _retryCount; i++)
         {
             if (context.FirstRunResults[0].Outcome == UnitTestOutcome.Passed)
                 break;

             var attempt = await context.ExecuteTaskGetter();
             result.AddResult(attempt);

             if (attempt[0].Outcome == UnitTestOutcome.Passed)
                 break;
         }

         return result;
     }
 }
 #pragma warning restore MSTESTEXP

 [TestClass]
 public class PaymentServiceTests
 {
     [TestMethod]
     [Retry(retryCount: 2)]
     public void ProcessPayment_ValidCard_Succeeds()
     {
         Assert.IsTrue(true);
     }

     [TestMethod]
     [Retry]
     public void ProcessPayment_ExpiredCard_Fails()
     {
         Assert.IsTrue(true);
     }
 }
